    original_bytes = source.read_bytes()
    source_digest = hashlib.sha256(original_bytes).hexdigest()
    original = original_bytes.decode()
    generated, regions = instrument(original, args.variant)
    output.mkdir(parents=True, exist_ok=False)
    preimage = output / 'preimage' / REL
    target = output / 'src' / REL
    helper = output / 'src' / HELPER_REL
    for directory in (preimage.parent, target.parent):
        directory.mkdir(parents=True)
    preimage.write_bytes(original_bytes)
    target.write_text(generated)
    shutil.copyfile(HERE / 'helper-src' / HELPER_REL, helper)
    patch = ''.join(difflib.unified_diff(original.splitlines(True), generated.splitlines(True),
                                       fromfile='a/' + str(PRODUCTION_REL), tofile='b/' + str(PRODUCTION_REL)))
    patch += ''.join(difflib.unified_diff([], helper.read_text().splitlines(True), fromfile='/dev/null',
                                        tofile='b/core/sail/lmdb/src/main/java/' + str(HELPER_REL)))
    (output / 'diagnostic-overlay.patch').write_text(patch)
    record = {'format': 1, 'variant': args.variant, 'sourceFile': str(source), 'sourceSha256': source_digest,
              'generatedSourceSha256': sha(target), 'helperSha256': sha(helper),
              'generatorFile': str(Path(__file__)), 'generatorSha256': sha(Path(__file__)),
              'unchangedSourceRegions': regions, 'patchSha256': sha(output / 'diagnostic-overlay.patch'),
              'runtimeOverlayClasses': [str(REL.with_suffix('.class')), str(HELPER_REL.with_suffix('.class'))],
              'javaExecuted': False, 'productionUnmodified': True}
    with (output / 'source-generation.json').open('x') as stream:
        json.dump(record, stream, indent=2, sort_keys=True)
        stream.write('\n')
    assert sha(source) == record['sourceSha256']
    print(json.dumps({'variant': args.variant, 'output': str(output), 'javaExecuted': False}))


